            aOrbiterD = ((aOrbiterD ^ aOrbiterI) ^ 0xEC9C7ADE0DAAAA98ULL) ^ aNonceWordE;
            aOrbiterD = RotL64((aOrbiterD * 0xCA3D3E6996A27BD1ULL), 3U);
