            aOrbiterD = (aOrbiterD + aOrbiterA) + 0x759E69374F8B1AE6ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0xDD8A78313DDEFD55ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x1A4FA05EF30B0CEDULL), 21U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterJ) + 0x4BA79C5101B4C25FULL) + aOrbiterUpdateSaltA[((aIndex + 3U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0xDB0609A4A6668E12ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xEA905CA070D9B975ULL), 11U);
