            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterF, 51U));
            aIngress = aIngress + RotL64(aOrbiterK, 5U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererG = aWandererG ^ (((RotL64(aScatter, 37U) + RotL64(aOrbiterJ, 5U)) + aOrbiterF) + aNonceWordP);
            aWandererC = aWandererC + (((RotL64(aIngress, 57U) + aOrbiterD) + RotL64(aOrbiterK, 35U)) + RotL64(aCarry, 35U));
            aWandererE = aWandererE ^ ((RotL64(aPrevious, 3U) + aOrbiterA) + RotL64(aOrbiterJ, 57U));
            aWandererD = aWandererD + ((RotL64(aCross, 30U) + RotL64(aOrbiterI, 21U)) + aOrbiterH);
