            aOrbiterK = (((aWandererH + RotL64(aScatter, 14U)) + 0x3BF96F3A061976ABULL) + aOrbiterAssignSaltF[(((31U - aIndex) + 8U)) & S_SALT1]) + aNonceWordB;
