            aOrbiterI = (aWandererA + RotL64(aIngress, 35U)) + 0x1BE85A78FE0CBF1BULL;
            aOrbiterJ = (((aWandererF + RotL64(aScatter, 3U)) + RotL64(aCarry, 19U)) + 0xFD98112155EBA378ULL) + aOrbiterAssignSaltC[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterE = (aWandererB + RotL64(aPrevious, 43U)) + 0x010F1B44BAFCE7E7ULL;
            aOrbiterB = (((aWandererJ + RotL64(aIngress, 52U)) + RotL64(aCarry, 27U)) + 0x0E510DEA3BDC3F08ULL) + aNonceWordH;
            aOrbiterH = ((aWandererE + RotL64(aCross, 27U)) + 0x0BD71704DA4C7E48ULL) + aNonceWordL;
            aOrbiterC = (aWandererG + RotL64(aIngress, 47U)) + 0xFAC878925CD4899AULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0xD172BAF82619C5BDULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterD) ^ 0x1203E6C8D8916C15ULL) ^ aOrbiterUpdateSaltC[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x32EED353AC6B2505ULL), 35U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0x9D854CD3AF37829BULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x4DF3435F5DCBD095ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xB0123BD08EAF9A9BULL), 43U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0x60C09557613215E8ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0xFA64E4A54E9B6CD1ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x0F05E077994B333BULL), 29U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterH) + 0x2D291BE2B52E328CULL) + aNonceWordO;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x08D58B604581EB1DULL;
            aOrbiterE = RotL64((aOrbiterE * 0xCFCF8A0493494F89ULL), 11U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x5B4684D9D2D19D1AULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x9479D415D0977F39ULL;
