            aOrbiterD = RotL64((aOrbiterD * 0xA05ED8DF9808C1DBULL), 23U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0x90F7945BD7495059ULL;
            aOrbiterK = (((aOrbiterK ^ aOrbiterC) ^ 0x9AE1B906C6DC2481ULL) ^ aOrbiterUpdateSaltB[((aIndex + 27U)) & S_SALT1]) ^ aNonceWordE;
