            //
            aWandererE = aWandererE + ((RotL64(aPrevious, 47U) + RotL64(aOrbiterB, 57U)) + aOrbiterK);
            aWandererC = aWandererC ^ (((RotL64(aScatter, 43U) + aOrbiterE) + RotL64(aOrbiterD, 53U)) + aWandererUpdateSaltA[((aIndex + 24U)) & S_SALT1]);
            aWandererK = aWandererK + (((RotL64(aCross, 23U) + aOrbiterH) + RotL64(aOrbiterJ, 5U)) + RotL64(aCarry, 39U));
            aWandererH = aWandererH ^ (((RotL64(aIngress, 38U) + RotL64(aOrbiterK, 22U)) + aOrbiterC) + aWandererUpdateSaltE[(((31U - aIndex) + 10U)) & S_SALT1]);
