            aOrbiterC = (((aWandererB + RotL64(aPrevious, 29U)) + RotL64(aCarry, 19U)) + 0x8778DA6AF70F3043ULL) + aPhaseAOrbiterAssignSaltC[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterB = (((aWandererJ + RotL64(aIngress, 60U)) + RotL64(aCarry, 53U)) + 0xEC8D1A6D38B1C0C0ULL) + aPhaseAOrbiterAssignSaltF[(((31U - aIndex) + 3U)) & S_SALT1];
