            aScatter = (RotL64(aIngress, 53U) ^ RotL64(aCross, 41U)) + (RotL64(aCarry, 20U) ^ RotL64(aPrevious, 5U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterH = ((aWandererF + RotL64(aCross, 37U)) + RotL64(aCarry, 5U)) + 0x70432E2FD559750AULL;
            aOrbiterJ = ((aWandererE + RotL64(aPrevious, 13U)) + 0x8D8C52F37D947E8DULL) + aPhaseCOrbiterAssignSaltE[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterB = ((aWandererB + RotL64(aIngress, 29U)) + RotL64(aCarry, 57U)) + 0x4F172160EAF473E3ULL;
            aOrbiterE = (aWandererC + RotL64(aScatter, 22U)) + 0x3642AA621EC5FBEDULL;
            aOrbiterG = (aWandererK + RotL64(aIngress, 57U)) + 0xEC4EAD154DD10444ULL;
            aOrbiterF = (((aWandererJ + RotL64(aScatter, 51U)) + RotL64(aCarry, 43U)) + 0x3663F4F2DD50B6DEULL) + aPhaseCOrbiterAssignSaltD[((aIndex + 5U)) & S_SALT1];
            aOrbiterK = (aWandererA + RotL64(aCross, 43U)) + 0xB82AAD2C9D253297ULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0x6C6B095117AAFDA7ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x23BE9C65BB3AD981ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x04054A40A8FE1E0DULL), 37U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x24B3D7E471868535ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0xC9A4A9D9A912E202ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xAB38BF60F88B3061ULL), 3U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x0AEC886B345D6C44ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterF) ^ 0xDD7774F5CDAE11BBULL) ^ aPhaseCOrbiterUpdateSaltB[((aIndex + 17U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x39182D97AE9DB281ULL), 21U);
            //
