            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0xF3EF783223E4B7C5ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x70A174B9763EBDF3ULL), 29U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0xE560A9D9B42276AEULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterB) ^ 0xEBA30E75E34F66F6ULL) ^ aPhaseCOrbiterUpdateSaltA[((aIndex + 21U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xC9D94935826585B7ULL), 47U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0xF077B681570B8BA9ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0xCC6098FC82BF0B52ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x48B89B0DD7EE2991ULL), 53U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0x3DA3463D9DC27C0CULL) + aPhaseCOrbiterUpdateSaltF[((aIndex + 4U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterK) ^ 0x63744794404593EEULL) ^ aPhaseCOrbiterUpdateSaltD[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xC81D24D903751B41ULL), 11U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterH, 56U);
