            //
            aCross = RotL64(aPoisonLaneC[((S_BLOCK1 - aIndex + 15958U)) & S_BLOCK1], 20U) ^ RotL64(aEarthLaneC[((aIndex + 12766U)) & S_BLOCK1], 51U);
