        //
        // Ingress:
        //      aWoodLaneA (-->), aFireLaneC (-->), aEarthLaneB (<-?->)
        //
        // Cross:
        //      aFireLaneA (<--), aFireLaneD (<--), aKeyRowReadB (<-?->)
