            aOrbiterA = ((aWandererF + RotL64(aIngress, 21U)) + RotL64(aCarry, 19U)) + 0x061E30F688489534ULL;
            aOrbiterK = ((aWandererC + RotL64(aCross, 13U)) + 0x0C2463F44CF7941CULL) + aPhaseCOrbiterAssignSaltA[(((31U - aIndex) + 11U)) & S_SALT1];
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0xD3F3F2C2F0CF444EULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterG) ^ 0x29B07839013CC151ULL) ^ aPhaseCOrbiterUpdateSaltD[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x6DC39863A5E227D7ULL), 27U);
