            aOrbiterA = (aWandererA + RotL64(aPrevious, 41U)) + 0xE80BA5C22AD7DE7AULL;
            aOrbiterG = ((aWandererD + RotL64(aIngress, 37U)) + 0x844CE29DEF8F11BBULL) + aPhaseBOrbiterAssignSaltF[((aIndex + 25U)) & S_SALT1];
