            aOrbiterI = (aOrbiterI + aOrbiterK) + 0xDC1BA9FCD6355CEDULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x6250AE6359DA8D48ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xCF2B13923C660721ULL), 27U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0x10B28C9E32E9EB2AULL) + aPhaseDOrbiterUpdateSaltE[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterE) ^ 0x7F48AE7668183CACULL) ^ aPhaseDOrbiterUpdateSaltF[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xBA4A3E4145813105ULL), 57U);
            //
            aIngress = aOrbiterK ^ RotL64(aOrbiterC, 10U);
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterE, 29U));
            aIngress = aIngress + (RotL64(aOrbiterG, 35U) ^ aOrbiterD);
            aIngress = aIngress + (RotL64(aOrbiterJ, 23U) ^ aOrbiterI);
            aIngress = aIngress + RotL64(aOrbiterA, 5U);
