            aIngress = (RotL64(aHeartLaneA[((aIndex + 4063U)) & S_BLOCK1], 13U) ^ RotL64(aHeartLaneB[((aIndex + 4664U)) & S_BLOCK1], 23U));
            aIngress ^= (RotL64(aEarthLaneC[((aIndex + 3577U)) & S_BLOCK1], 57U) ^ RotL64(aPoisonLaneC[((aIndex + 993U)) & S_BLOCK1], 42U));
