            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aIngress, 37U) + RotL64(aCarry, 19U)) ^ (RotL64(aPrevious, 52U) + RotL64(aCross, 5U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterF = (aWandererG + RotL64(aScatter, 3U)) + 0x8544140B6D7977CBULL;
            aOrbiterG = ((aWandererJ + RotL64(aIngress, 47U)) + 0xB25579E0953E776BULL) + aPhaseAOrbiterAssignSaltD[((aIndex + 16U)) & S_SALT1];
            aOrbiterB = ((aWandererK + RotL64(aPrevious, 23U)) + 0xA65B230421F6536EULL) + aPhaseAOrbiterAssignSaltB[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterD = ((aWandererC + RotL64(aCross, 54U)) + RotL64(aCarry, 41U)) + 0xE15A32F0FEC88123ULL;
            aOrbiterA = (aWandererH + RotL64(aScatter, 39U)) + 0xB187EBC2241A9047ULL;
            aOrbiterC = ((aWandererD + RotL64(aPrevious, 13U)) + RotL64(aCarry, 53U)) + 0xC40E308D9BB433C9ULL;
            aOrbiterH = ((aWandererF + RotL64(aIngress, 29U)) + RotL64(aCarry, 5U)) + 0xB617C4A5D5F73820ULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0xD462C6B7BDE71CB5ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterF) ^ 0x9C56988AEB2D81F1ULL) ^ aPhaseAOrbiterUpdateSaltD[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xA5B18B5FB8925F59ULL), 5U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterD) + 0x3F56E779E3D4BC39ULL) + aPhaseAOrbiterUpdateSaltA[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0xAAFC28F5DE564F3BULL;
            aOrbiterA = RotL64((aOrbiterA * 0x5DA1A589C22675ADULL), 43U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterC) + 0xC154EEE6E60595C5ULL) + aPhaseAOrbiterUpdateSaltB[((aIndex + 23U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0x5F143A38564AE23AULL) ^ aPhaseAOrbiterUpdateSaltC[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xA9FB230679743B69ULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x2999ECF618A22836ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0x7AB1C53C1CF16C2EULL;
            aOrbiterF = RotL64((aOrbiterF * 0x0F97182F82C8ED8DULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x24E355790460E39DULL;
