            //
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 21U) + aOrbiterD) + RotL64(aOrbiterG, 42U));
            aWandererJ = aWandererJ + ((RotL64(aIngress, 50U) + aOrbiterA) + RotL64(aOrbiterG, 51U));
            aWandererF = aWandererF ^ ((RotL64(aScatter, 27U) + RotL64(aOrbiterG, 35U)) + aOrbiterH);
            aWandererG = aWandererG + (((RotL64(aCross, 5U) + RotL64(aOrbiterF, 5U)) + aOrbiterG) + RotL64(aCarry, 41U));
