            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0x98F649DD6C9CDB9EULL) + aPhaseCOrbiterUpdateSaltA[((aIndex + 28U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0xAEC7B11C1F74F7DDULL;
